<script setup>import{onMounted}from'vue';import{useContract}from'../composables/useContract.js';import BottomNav from'../components/BottomNav.vue';const{loading,error,installments,load}=useContract();const money=v=>new Intl.NumberFormat('th-TH',{minimumFractionDigits:2}).format(Number(v||0));onMounted(load)</script><template><main class="app-shell"><header class="page-head"><RouterLink to="/dashboard">‹</RouterLink><h1>ตารางผ่อน</h1></header><div v-if="loading" class="card state">กำลังโหลด...</div><div v-else-if="error" class="card alert error">{{error}}</div><section v-else class="card"><div v-for="i in installments" :key="i.id" class="schedule-row"><b>งวด {{i.installment_no}}</b><span>คน 1: {{money(i.payer1_amount)}}</span><span>คน 2: {{money(i.payer2_amount)}}</span><strong>{{money(i.amount)}}</strong><RouterLink :to="'/payment/'+i.id">›</RouterLink></div></section><BottomNav/></main></template>
